#!/usr/bin/env bash
# Docs check: in the user and contributor docs, every relative link points at a file that exists, every
# backticked repo path exists, and every `./install.sh <word>` uses a command or flag that --help lists.
# Reads docs/ (not docs/history/), README.md, CONTRIBUTING.md, module READMEs and bar item READMEs.
# docs/settings-reference.md may be missing for now (it is generated by another step): that prints a note.
# Run by tests/lint.sh (CI) or by hand: tests/docs.sh
# shellcheck disable=SC2016  # the grep patterns hold literal backticks and \$ on purpose
set -uo pipefail
cd "$(dirname "$0")/.." || exit 1
fail=0
problem() {
    echo "xx $*"
    fail=1
}

help=$(./install.sh --help)
files=(README.md CONTRIBUTING.md modules/*/README.md config/quickshell/.config/quickshell/bar/items/*/README.md)
while IFS= read -r f; do files+=("$f"); done < <(find docs -name '*.md' -not -path 'docs/history/*' | sort)

for f in "${files[@]}"; do
    [[ -f $f ]] || continue
    [[ $f == docs/audit/* ]] && continue # dated review of an older commit: it cites old paths on purpose
    dir=$(dirname "$f")
    # (a) relative links: [text](target)
    while IFS= read -r target; do
        target=${target%%#*}
        [[ -z $target || $target == http* || $target == mailto:* ]] && continue
        if [[ ! -e $dir/$target ]]; then
            if [[ $(basename "$target") == settings-reference.md ]]; then
                echo "note: $f: $target does not exist yet"
            else
                problem "$f: broken link $target"
            fi
        fi
    done < <(grep -oE '\]\([^)[:space:]]+\)' "$f" | sed -E 's/^\]\(//; s/\)$//')
    # (b) backticked paths that start with a top-level repo folder
    while IFS= read -r p; do
        [[ $p == *[\<\*…]* || $p == *NNNN* ]] && continue # placeholders
        p=${p%%[[:space:]]*}
        p=${p%:[0-9]*} # file:line
        p=${p%/}
        [[ $p == tests/fixtures ]] && continue # shortcut: named in CONVENTIONS.md but not a folder yet, drop this line when it is
        [[ -e $p ]] || problem "$f: path not found $p"
    done < <(grep -oE '`(config|distros|docs|lib|migrations|modules|packages|plugins|tests|themes)/[^`]*`' "$f" | tr -d '`')
    # (c) ./install.sh commands and flags
    while IFS= read -r w; do
        grep -qE "(^|[[:space:]])$w([[:space:]]|\$)" <<<"$help" || problem "$f: ./install.sh $w is not in --help"
    done < <(grep -oE '\./install\.sh +[a-z]+' "$f" | awk '{print $2}' | sort -u)
    while IFS= read -r w; do
        [[ $w == --help ]] && continue # works, but is not listed in its own help
        grep -qE -- "(^|[[:space:]])$w([[:space:]]|\$)" <<<"$help" || problem "$f: ./install.sh $w is not in --help"
    done < <(grep -oE '\./install\.sh[^`]* --[a-z-]+' "$f" | grep -oE -- '--[a-z-]+$' | sort -u)
done

((fail == 0)) && echo "ok: docs links, paths and install.sh commands"
exit "$fail"
